 autoFlow(){const runtime=RuntimeCompiler.compile(this.doc),newFlow=generateFlowAnchors(this.doc,runtime),before=this.doc.flow.map(clone),after=newFlow.map(clone),cmd={do:()=>{this.doc.flow=clone(after)},undo:()=>{this.doc.flow=clone(before)}};this.commands.execute(cmd);this.toast('Bot routes rebuilt')} autoGameplay(){if(!this.doc)return;const beforeSpawns=this.doc.spawns.map(clone),beforeFlow=this.doc.flow.map(clone),runtime=RuntimeCompiler.compile(this.doc),L=Math.max(18,Math.min(this.doc.minimapLimit,this.doc.arenaLimit)-7),next=this.doc.spawns.map(clone),safe=(team,index)=>{const side=team==='blue'?-1:1,baseX=side*L,targetZ=-L*.62+index*(L*1.24/3),offsets=[0,4,-4,8,-8,12,-12,16,-16];for(let inward=0;inward<=Math.min(30,L*.45);inward+=2){const x=baseX-side*inward;for(const oz of offsets){const z=clamp(targetZ+oz,-L,L);if(Validator.blocked(this.doc,x,z,1.1,runtime)||Validator.slope(this.doc,x,z,runtime)>.45)continue;if(next.some(s=>Math.hypot(s.x-x,s.z-z)<3.5))continue;return{x,z}}}return{x:side*(L*.75),z:targetZ}};for(const team of ['blue','red']){let count=next.filter(s=>s.team===team).length;for(let i=count;i<4;i++){const p=safe(team,i);next.push({id:uid('spawn'),type:'spawn',team,x:p.x,z:p.z,yOffset:0,yaw:team==='red'?180:0})}}const nextFlow=generateFlowAnchors(this.doc,runtime),afterSpawns=clone(next),afterFlow=clone(nextFlow),cmd={do:()=>{this.doc.spawns=clone(afterSpawns);this.doc.flow=clone(afterFlow)},undo:()=>{this.doc.spawns=clone(beforeSpawns);this.doc.flow=clone(beforeFlow)}};this.commands.execute(cmd);this.toast('Setup ready · team starts and bot routes added');this.renderCatalog()}
