 renderLayers(){const names={terrain:'Terrain',roads:'Roads',build:'Structures',props:'Props & Nature',gameplay:'Gameplay / Spawns',flow:'Bot Flow'},root=$('layersBody');root.innerHTML='<div style="color:var(--muted);font-size:10px;line-height:1.4;margin-bottom:8px">Hidden layers are omitted from 2D/3D. Locked layers remain visible but cannot be selected.</div>';for(const k of Object.keys(names)){const st=this.layerState[k],row=document.createElement('div');row.className='layer-row';row.innerHTML=`<div><b>${names[k]}</b><small>${st.visible?'Visible':'Hidden'} · ${st.locked?'Locked':'Editable'}</small></div><button class="toggle ${st.visible?'on':''}" data-vis="${k}">◉</button><button class="toggle ${st.locked?'on':''}" data-lock="${k}">${st.locked?'🔒':'○'}</button>`;root.appendChild(row)}root.querySelectorAll('[data-vis]').forEach(b=>b.onclick=()=>{const k=b.dataset.vis;this.layerState[k].visible=!this.layerState[k].visible;if(k==='flow')this.showFlow=this.layerState[k].visible;this.sceneRev++;this.renderLayers();this.draw()});root.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>{const k=b.dataset.lock;this.layerState[k].locked=!this.layerState[k].locked;if(this.layerState[k].locked){for(const id of [...this.selected]){const o=this.doc.get(id);if(o&&this.layerFor(o)===k)this.selected.delete(id)}this.syncUI()}this.renderLayers();this.draw()})}
 renderSnapping(){const s=this.snapConfig,root=$('snapBody');root.innerHTML=`<div class="snap-row"><div><b>Grid snap</b><small>Snap movement and placement to a regular grid.</small></div><button class="toggle ${s.grid?'on':''}" data-snap-toggle="grid">${s.grid?'ON':'OFF'}</button><span></span></div><div class="field"><label>GRID SIZE</label><input id="snapGridSize" type="number" min="0.25" max="10" step="0.25" value="${s.gridSize}"></div><div class="snap-row"><div><b>Smart object guides</b><small>Align centers and edges to nearby objects.</small></div><button class="toggle ${s.objects?'on':''}" data-snap-toggle="objects">${s.objects?'ON':'OFF'}</button><span></span></div><div class="snap-row"><div><b>Road network snap</b><small>Snap roads to endpoints and T-junctions.</small></div><button class="toggle ${s.roads?'on':''}" data-snap-toggle="roads">${s.roads?'ON':'OFF'}</button><span></span></div><div class="field"><label>ROTATION SNAP</label><select id="snapAngle"><option value="1">1°</option><option value="5">5°</option><option value="15">15°</option><option value="45">45°</option><option value="90">90°</option></select></div>`;$('snapAngle').value=String(s.angle);root.querySelectorAll('[data-snap-toggle]').forEach(b=>b.onclick=()=>{const k=b.dataset.snapToggle;this.snapConfig[k]=!this.snapConfig[k];this.renderSnapping()});$('snapGridSize').onchange=e=>{this.snapConfig.gridSize=clamp(num(e.target.value,1),.25,10);this.renderSnapping()};$('snapAngle').onchange=e=>this.snapConfig.angle=num(e.target.value,15)}
 snapPoint(x,z,exclude=new Set()){let sx=this.snap(x),sz=this.snap(z),guides=[];if(!this.snapConfig.objects||!this.doc)return{x:sx,z:sz,guides};const threshold=12/Math.max(.35,this.view.scale);let bx=threshold,bz=threshold;for(const o of this.doc.all()){if(exclude.has(o.id)||!this.layerVisible(this.layerFor(o)))continue;const xs=[o.x],zs=[o.z];if(['road','building','prop','elevation'].includes(o.type)){const cs=Resolver.rectCorners(o);for(const p of cs){xs.push(p.x);zs.push(p.z)}}for(const v of xs){const d=Math.abs(v-x);if(d<bx){bx=d;sx=v;guides=guides.filter(g=>g.axis!=='x');guides.push({axis:'x',x:v})}}for(const v of zs){const d=Math.abs(v-z);if(d<bz){bz=d;sz=v;guides=guides.filter(g=>g.axis!=='z');guides.push({axis:'z',z:v})}}}return{x:sx,z:sz,guides}}
