async function saveServerMap(){const out=editor.exportData(),data=await builderApi('/maps/save',{mapId:serverMapId||undefined,name:out.meta?.name,map:out});serverMapId=data.mapId||data.map?.id||serverMapId;setServerDirty(false);editor.setSaveState('saved');editor.toast('Draft saved to Breach');onSaved?.({mapId:serverMapId,published:false,map:data.map||null});return data;}
async function publishServerMap(){prepareSimpleStarts();const issues=Validator.validate(editor.doc,true),status=Validator.statusFrom(issues);if(!status.exportable){const issue=issues.find(i=>i.tone==='bad');if(editor.walk)editor.walk.showIssue(issue);else editor.showChecks();return null}await saveServerMap();const data=await builderApi('/maps/publish',{mapId:serverMapId});editor.setSaveState('saved');editor.toast(`Published revision ${data.revision}`);onSaved?.({mapId:serverMapId,published:true,revision:data.revision,map:data.map||null});return data;}
