function completeExit(){gameRuntime?.close();editor.walk?.exit();if(editor.play.active)editor.stopPlay();builderController.cursor=false;builderController.roadStart=null;editor.controllerCursorActive=false;builderControllerClearFocus();$('exitConfirm').classList.add('hide');active=false;onExit?.({mapId:serverMapId});}
function requestExit(){if(serverDirty){$('exitConfirm').classList.remove('hide');return}completeExit();}
function bindServerMapActions(){const back=$('backToGameBtn'),save=$('saveServerBtn'),publish=$('publishServerBtn');if(back)back.onclick=requestExit;if(save)save.onclick=async()=>{save.disabled=true;try{await saveServerMap()}catch(error){editor.reportProblem(error,{title:'DRAFT NOT SAVED',what:'Breach could not save this draft to the server.',where:'SAVE DRAFT',fix:'Your local autosave remains available. Check the connection, then press SAVE DRAFT again.'})}finally{save.disabled=false}};if(publish)publish.onclick=async()=>{publish.disabled=true;try{await publishServerMap()}catch(error){editor.reportProblem(error,{title:'PUBLISH FAILED',what:'The map passed local readiness checks but the server did not publish it.',where:'PUBLISH',fix:'The draft is still available. Retry Publish; if it repeats, use the technical details below.'})}finally{publish.disabled=false}};$('menuSaveServer').onclick=()=>{$('moreMenu').classList.add('hide');save?.click()};$('menuPublishServer').onclick=()=>{$('moreMenu').classList.add('hide');publish?.click()};$('menuExportMap').onclick=()=>{$('moreMenu').classList.add('hide');editor.showChecks()};$('exitStayBtn').onclick=()=>$('exitConfirm').classList.add('hide');$('exitDiscardBtn').onclick=()=>completeExit();$('exitSaveBtn').onclick=async()=>{const b=$('exitSaveBtn');b.disabled=true;try{await saveServerMap();completeExit()}catch(error){editor.reportProblem(error,{title:'DRAFT NOT SAVED',what:'The draft could not be saved before exit.',where:'SAVE & EXIT',fix:'Keep editing and retry SAVE DRAFT. Your local autosave remains available.'})}finally{b.disabled=false}};}
bindServerMapActions();
