window.__BreachBuilder=debugApi;
async function open({mapId='' }={}){
  active=true;builderController.cursor=false;builderController.roadStart=null;builderControllerClearFocus();editor.controllerCursorActive=false;
  serverMapId=String(mapId||'');
  $('exitConfirm').classList.add('hide');
  if(editor.play.active)editor.stopPlay();
  gameRuntime?.close();
  editor.closeDrawers();
  if(serverMapId){
    $('welcome').classList.add('hide');
    await loadServerMap();
  }else{
    editor.setDoc(templateToDoc('blank'));
  }
  requestAnimationFrame(()=>{if(active&&editor.doc)editor.draw();});
  return true;
}
function close({force=false}={}){if(!active)return true;if(!force&&serverDirty){requestExit();return false}completeExit();return true;}
